import{_ as e,o as t,c as o,a2 as s}from"./chunks/framework.CeYlivdO.js";const g=JSON.parse('{"title":"深入理解CC++的编译与链接技术3：如何制作和使用静态库","description":"","frontmatter":{"title":"深入理解CC++的编译与链接技术3：如何制作和使用静态库","description":"","tags":["cpp-modern","host","intermediate"],"difficulty":"intermediate","platform":"host","chapter":13,"order":3},"headers":[],"relativePath":"compilation/03-creating-and-using-static-libs.md","filePath":"compilation/03-creating-and-using-static-libs.md","lastUpdated":null}'),i={name:"compilation/03-creating-and-using-static-libs.md"};function r(n,a,d,l,c,h){return t(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="深入理解cc-的编译与链接技术3-如何制作和使用静态库" tabindex="-1">深入理解CC++的编译与链接技术3：如何制作和使用静态库 <a class="header-anchor" href="#深入理解cc-的编译与链接技术3-如何制作和使用静态库" aria-label="Permalink to &quot;深入理解CC++的编译与链接技术3：如何制作和使用静态库&quot;">​</a></h1><p>在上一篇博客中，笔者就简单的提及了一下关于静态库和动态库的基本导论，笔者将链接放在这里：</p><blockquote><p><a href="https://blog.csdn.net/charlie114514191/article/details/152921903" target="_blank" rel="noreferrer">深入理解CC++的编译与链接技术-CSDN博客</a></p><p><a href="https://blog.csdn.net/charlie114514191/article/details/154828385" target="_blank" rel="noreferrer">深入理解CC++的编译与链接技术2：动态库静态库导论-CSDN博客</a></p></blockquote><p>所以在之前，我们就简单的讲述了静态库的本质是什么。尽管，在今天，使用动态库作为代码的共享是一种更加基本的策略。但是处于完整，和笔者自己也喜欢用静态库打包一个只依赖于<code>C/C++</code>最基本运行时的人（其实笔者的确没有什么技术原因选择，纯粹是不太喜欢将一大坨可重定位文件直接塞给Linker）</p><h2 id="如何制作静态库" tabindex="-1">如何制作静态库？ <a class="header-anchor" href="#如何制作静态库" aria-label="Permalink to &quot;如何制作静态库？&quot;">​</a></h2><h3 id="ar工具" tabindex="-1"><code>ar</code>工具 <a class="header-anchor" href="#ar工具" aria-label="Permalink to &quot;`ar`工具&quot;">​</a></h3><p>所以一个很自然的问题出现了，在之前我们学习了静态库的最基本的原理（若干可重定位文件的有机组合），那又如何制作它呢？答案是利用一个小巧而强大的工具——<code>ar</code>（Archiver）</p><p>简单的介绍一下<code>ar</code>吧！它是一个用于创建、修改和提取<strong>归档文件</strong>（Archive Files）的工具。这些归档文件通常以 <code>.a</code> （a是archive，归档的缩写）扩展名结尾，最常见的用途就是打包目标文件（<code>.o</code> 文件）来创建 <strong>静态链接库</strong>（Static Libraries）。对于Linux而言，我们喜欢给一个静态库（至少是静态库），假设库的名字我们决定叫<code>Charlie</code>，那么一般我们生成的库会是<code>libCharlie.a</code></p><p>可能会有朋友困惑，为什么一定是lib起头，生成<code>Charlie.a</code>显然不是更加的直观吗？是这样的，最核心的原因是：<strong>这是后续我们拿来做链接的时候，链接器存在的工作约定要求导致的</strong>。最经常的，我们<code>gcc/g++</code>编译准备链接对象的时候，会发派发ld来链接目标的库和重定位文件，一般而言，上层构建工具会习惯采用-L文件夹检索路径配合-l（这是小写的L）找库。比如说，当我们试图给main.c提供知名路径下的math静态库，比如说咱们这样写：</p><div class="language-cpp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gcc main.c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lmath</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>链接器并不会直接去寻找名为 <code>math</code> 的文件。相反，它会根据约定，尝试寻找名为 <strong><code>libmath.a</code></strong>（静态库）或 <strong><code>libmath.so</code></strong>（动态库）的文件。简单的说就是：</p><ul><li><code>-l</code> 参数后面的名字（本例中的 <code>math</code>）被称为&quot;库名&quot;。</li><li>链接器会自动在这个名字前加上前缀 <code>lib</code>。</li><li>然后根据情况（和优先级）加上 <code>.a</code>（静态库）或 <code>.so</code>（动态库）等后缀，从而构成完整的文件名。</li></ul><p>因此，<strong>将库文件命名为 <code>lib&lt;name&gt;.a</code> 的格式，是为了主动迎合链接器的自动查找机制</strong>。如果库文件不以此格式命名，链接器就无法通过简便的 <code>-l</code> 选项找到它，你只能通过直接指定库文件完整路径的笨拙方式来链接，这非常不方便，而且出现一个很严重的问题，这个问题将会在动态库的时候我们重新拿出来说（静态库无所谓，它会被打包进去目标的文件）</p><h3 id="ar的一些常用命令格式" tabindex="-1"><code>ar</code>的一些常用命令格式 <a class="header-anchor" href="#ar的一些常用命令格式" aria-label="Permalink to &quot;`ar`的一些常用命令格式&quot;">​</a></h3><p><code>ar</code> 的基本语法相对简单，它需要一个<strong>操作码</strong>（类似于一个主命令）和一些<strong>修饰符</strong>（Modifier）来指定具体行为。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [操作码][修饰符] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">归档文件名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">文件...</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th><strong>操作码</strong></th><th><strong>描述</strong></th><th><strong>常用修饰符</strong></th><th><strong>示例命令</strong></th></tr></thead><tbody><tr><td><strong><code>r</code></strong></td><td><strong>插入/替换</strong>：将文件添加到归档中。如果归档中已存在同名文件，则替换它。</td><td><code>v</code> (显示详细信息)</td><td><code>ar rv libmy.a file1.o file2.o</code></td></tr><tr><td><strong><code>t</code></strong></td><td><strong>列表</strong>：显示归档中包含的文件列表。</td><td><code>v</code> (显示详细信息)</td><td><code>ar t libmy.a</code></td></tr><tr><td><strong><code>x</code></strong></td><td><strong>提取</strong>：从归档中提取（解包）文件。</td><td><code>v</code> (显示详细信息)</td><td><code>ar xv libmy.a</code></td></tr></tbody></table><blockquote><p>查看Man手册总是好的：<a href="https://linux.die.net/man/1/ar" target="_blank" rel="noreferrer">ar(1) - Linux man page</a></p></blockquote><h3 id="windows呢" tabindex="-1">Windows呢？ <a class="header-anchor" href="#windows呢" aria-label="Permalink to &quot;Windows呢？&quot;">​</a></h3><p>这个事情其实是MSVC工具链搞定它，不过，鲜有人自己手动做这些事情，在Windows上，大家基本都是委托巨无霸IDE: Visual Studio，或者是笔者喜欢用轻量的Visual Studio Code委托CMake处理这个事情。具体的细节可以去看看CMake编译的详细日志，这里笔者处于篇幅不计划展开</p><h2 id="我们在什么地方会使用静态库呢" tabindex="-1">我们在什么地方会使用静态库呢？ <a class="header-anchor" href="#我们在什么地方会使用静态库呢" aria-label="Permalink to &quot;我们在什么地方会使用静态库呢？&quot;">​</a></h2><p>笔者仔细想了想，稍微结合了一下自己粗浅的工程经验（可以说几乎没有）和自己看过的一点资料，其实在今天，静态库几乎可以被动态库所替代了，但是在这些场景下，使用静态库显然更加的合适，当然，笔者在嵌入式中使用静态库显然多一些，所以就打算这样说：</p><ul><li><strong>分发简单化：</strong> 只需要分发一个可执行文件，无需携带一堆<code>.dll</code> (Windows) 或 <code>.so</code>/<code>.dylib</code> (Linux/macOS) 文件。</li><li><strong>版本锁死：</strong> 你需要<strong>绝对保证</strong>你的程序使用的是特定版本的库，不会被用户系统上的其他版本干扰。</li><li><strong>小型工具或嵌入式系统：</strong> 在对文件数量或动态链接支持有严格限制的环境中。</li></ul><h2 id="那反过来-不使用静态库的理由呢" tabindex="-1">那反过来，不使用静态库的理由呢 <a class="header-anchor" href="#那反过来-不使用静态库的理由呢" aria-label="Permalink to &quot;那反过来，不使用静态库的理由呢&quot;">​</a></h2><p>回顾上一个博客，我们已经说明了静态库的工作原理。所以，很容易想到第一个不使用静态库的理由就是：</p><h4 id="可执行文件尺寸剧增-executable-bloat" tabindex="-1">可执行文件尺寸剧增 (Executable Bloat) <a class="header-anchor" href="#可执行文件尺寸剧增-executable-bloat" aria-label="Permalink to &quot;可执行文件尺寸剧增 (Executable Bloat)&quot;">​</a></h4><p>在注重<strong>复用接口</strong>的情况下，显然使用静态库会导致所有依赖于此的库和可执行文件的尺寸剧增 (Executable Bloat)，所以，<strong>任何那些目的是给其他依赖提供功能接口，自身绝对独立的模块，请使用动态库</strong>。这个时候，我们让代码依赖只存在一份，让操作系统和加载器自动协调所有的映射符号关系，显然更好</p><h4 id="更新需要重新编译和发布-hot-reloading-request" tabindex="-1">更新需要重新编译和发布（Hot Reloading Request） <a class="header-anchor" href="#更新需要重新编译和发布-hot-reloading-request" aria-label="Permalink to &quot;更新需要重新编译和发布（Hot Reloading Request）&quot;">​</a></h4><p>在注重<strong>热更新</strong>的场景下，显然采用静态库不合理，比如说，一些包我们不方便直接替换掉可执行文件，而是只用更新其中的一个子依赖的时候（比如说，我们采用的一个库被一个热心的开源主义程序员发现了漏洞并且及时向您反馈），即我们发现了库中一个安全漏洞或需要修复一个Bug，采用静态库我们必须<strong>重新编译并重新分发整个应用程序（静态链接让这些代码成为了本体的一部分而不是需要的依赖）</strong></p><h4 id="潜在的符号冲突和版本管理问题-symbol-collisions" tabindex="-1">潜在的符号冲突和版本管理问题 (Symbol Collisions) <a class="header-anchor" href="#潜在的符号冲突和版本管理问题-symbol-collisions" aria-label="Permalink to &quot;潜在的符号冲突和版本管理问题 (Symbol Collisions)&quot;">​</a></h4><p>如果我们将<strong>多个版本</strong>或<strong>同名符号</strong>的静态库链接到同一个可执行文件中，编译器/链接器会尝试解决，但风险很高（笔者没有记错的话，是按照符号强弱和等同下随机丢弃），这真的很危险，谁也不喜欢自己的程序猜猜乐。</p>',31)])])}const b=e(i,[["render",r]]);export{g as __pageData,b as default};
